<script lang="ts">
  import {onDestroy,untrack} from 'svelte';
  import {loadWorkflow,loadWorkQueue,type WorkflowConfiguration,type WorkQueue} from '../api/workflows';
  import {focusDialog} from '../util/focusDialog';
  let {moduleUid,moduleName,revision=0,onOpen}:{moduleUid:string;moduleName:string;revision?:number;onOpen:(uid:string)=>void}=$props();
  let configuration=$state<WorkflowConfiguration|null>(null);let open=$state(false);let queue=$state<WorkQueue|null>(null);let loading=$state(false);let error=$state('');let configError=$state('');
  let stageFilter=$state('');let actionable=$state(false);let after=$state('');let previous=$state<string[]>([]);let controller:AbortController|undefined;let configController:AbortController|undefined;
  let generation=0;let dead=false;let trigger=$state<HTMLButtonElement>();
  $effect(()=>{moduleUid;revision;untrack(()=>void configurationChanged());});
  onDestroy(()=>{dead=true;controller?.abort();configController?.abort();generation++;});
  async function configurationChanged(){configController?.abort();const request=new AbortController();configController=request;try{const next=await loadWorkflow(moduleUid,request.signal);if(request.signal.aborted||dead)return;const changed=next.revision!==configuration?.revision;configuration=next;configError='';if(changed){stageFilter='';after='';previous=[];}if(open)void reload();}catch(reason){if(!request.signal.aborted&&!dead)configError=reason instanceof Error?reason.message:String(reason);}}
  async function reload(){controller?.abort();const request=new AbortController();controller=request;const current=++generation;loading=true;error='';try{const result=await loadWorkQueue(moduleUid,{after,state:stageFilter,actionable},request.signal);if(!dead&&current===generation){queue=result;if(result.enabled&&result.configuration_revision!==configuration?.revision)void configurationChanged();}}catch(reason){if(!request.signal.aborted&&!dead)error=reason instanceof Error?reason.message:String(reason);}finally{if(current===generation)loading=false;}}
  function filtersChanged(){after='';previous=[];void reload();}
  function close(){open=false;controller?.abort();generation++;loading=false;trigger?.focus();}
  function next(){if(!queue?.has_next||!queue.next_cursor)return;previous.push(after);after=queue.next_cursor;void reload();}
  function back(){if(!previous.length)return;after=previous.pop()!;void reload();}
</script>
{#if configuration?.definition.enabled}<button bind:this={trigger} class="button" type="button" onclick={()=>{open=true;void reload();}}>Work queue</button>{:else if configError}<button class="button" type="button" title={configError} onclick={configurationChanged}>Retry process availability</button>{/if}
{#if open}
<div class="overlay work-queue-overlay" role="presentation" onclick={event=>{if(event.target===event.currentTarget)close();}}>
<div class="dialog work-queue" role="dialog" aria-modal="true" aria-labelledby="work-queue-title" tabindex="-1" use:focusDialog onkeydown={event=>{if(event.key==='Escape'){event.preventDefault();event.stopPropagation();close();}}}>
  <header class="dialog-head"><div><p class="eyebrow">Module · {moduleName}</p><h2 id="work-queue-title">{configuration?.definition.name||'Work queue'}</h2><p>Find records by process stage, review their saved values and take permitted actions.</p></div><button class="button" type="button" onclick={close}>Close queue</button></header>
  <div class="queue-body"><div class="queue-filters"><label>Stage<select bind:value={stageFilter} onchange={filtersChanged}><option value="">All stages</option>{#each configuration?.definition.states||[] as s}<option value={s.key}>{s.name}</option>{/each}</select></label><label class="checkbox"><input type="checkbox" bind:checked={actionable} onchange={filtersChanged}/>Only records where I may act</label><button class="button" type="button" disabled={loading} onclick={reload}>Refresh queue</button></div>
    {#if error}<p class="notice error" role="alert">{error}</p>{/if}{#if loading}<p role="status">Loading work queue…</p>{/if}
    {#if queue&&!loading&&!queue.enabled}<p class="notice">This process has been disabled. Its history is preserved in each record.</p>{:else}
    <div class="queue-items" aria-busy={loading}>{#each queue?.items||[] as item}<article><div><h3>{item.title}</h3><p><strong>{item.state_name}</strong>{#if item.restarted}<span> · Changed; review required</span>{/if}</p><small>{item.actions?.length?`Available: ${item.actions.map(a=>a.name).join(' · ')}`:'No actions available to your account'}{#if item.actions?.some(a=>a.missing_fields.length)} · Required information is incomplete{/if}</small></div><button class="button" type="button" disabled={loading} onclick={()=>{close();onOpen(item.uid);}}>Review record</button></article>{/each}</div>
    {#if queue&&!queue.items.length&&!loading}<p class="empty-state compact">No records match this queue. Create records in the module, or change the stage filter.</p>{/if}{/if}
  </div><footer><small>Up to 40 records per page · Only records you may view are included</small><div><button class="button" type="button" disabled={loading||!previous.length} onclick={back}>Previous</button><button class="button" type="button" disabled={loading||!queue?.has_next} onclick={next}>Next</button></div></footer>
</div></div>{/if}
<style>
  .work-queue{width:min(68rem,100%);max-height:calc(100dvh - 2rem);display:flex;flex-direction:column;padding:0;overflow:hidden}.dialog-head{padding:1rem;margin:0;border-bottom:1px solid var(--line);gap:1rem}.dialog-head p{color:var(--muted);margin:.4rem 0 0}.dialog-head h2{font-size:1.2rem;margin:0}.queue-body{padding:1rem;overflow:auto;min-height:0}.queue-filters{display:flex;align-items:end;gap:1rem;flex-wrap:wrap;margin-bottom:1rem}.queue-filters label:not(.checkbox){display:grid;gap:.4rem;min-width:12rem}.checkbox{display:flex;gap:.5rem;align-items:center;align-self:center}.queue-items{display:grid;gap:.65rem}.queue-items article{display:flex;align-items:center;gap:1rem;justify-content:space-between;border:1px solid var(--line);border-radius:.5rem;padding:.85rem;min-width:0}.queue-items article>div{min-width:0}.queue-items h3{margin:0;font-size:1rem;overflow-wrap:anywhere}.queue-items p{margin:.35rem 0}.queue-items button{flex-shrink:0}small{font-size:.875rem;color:var(--muted);overflow-wrap:anywhere}footer{padding:.85rem 1rem;border-top:1px solid var(--line);display:flex;justify-content:space-between;align-items:center;gap:.75rem;flex-wrap:wrap}footer>div{display:flex;gap:.5rem}@media(max-width:600px){.queue-items article{align-items:start;flex-direction:column}.queue-filters label:not(.checkbox){flex:1}.work-queue{max-height:calc(100dvh - 1rem)}}
</style>
